const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${pathIcons[name]||pathIcons.receipt}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dollars=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
const fmt=cents=>'US'+dollars(cents);
const allSamples=[
 {id:'0428',kind:'hotel',name:'Singapore · two nights',offer:'Hotel booking',detail:'Singapore · 8–10 Oct · 1 adult',provider:'Nuitée',providerEnv:'Sandbox',agent:'ChatGPT',channel:'External agent',rail:'Cardano',network:'Preprod',amount:28600,newAmount:31200,ceiling:40000,request:'Book two nights in Singapore. Keep the total under US$400.',status:'executing',time:'10:14 AM',reference:'DEMO-NUITEE-024'},
 {id:'0427',kind:'retail',name:'Noise-cancelling headphones',offer:'Headphones · sample product',detail:'1 item · delivery included',provider:'Shopify',providerEnv:'Test store',agent:'Claude',channel:'MCP',rail:'Solana',network:'Devnet',amount:7900,newAmount:8500,ceiling:10000,request:'Buy these headphones from our test store. Keep the delivered price under US$100.',status:'succeeded',time:'10:08 AM',reference:'DEMO-SHOPIFY-1042'},
 {id:'0426',kind:'flight',name:'Singapore → Tokyo',offer:'Flight reservation',detail:'SIN → NRT · 12 Oct · 1 adult',provider:'Atlas',providerEnv:'Sandbox',agent:'Claude',channel:'MCP',rail:'Cardano',network:'Preprod',amount:41200,newAmount:43900,ceiling:50000,request:'Book this Singapore to Tokyo flight for one adult, under US$500.',status:'executing',time:'9:52 AM',reference:'DEMO-ATLAS-082'},
 {id:'0425',kind:'hotel',name:'Bangkok · one night',offer:'Hotel booking',detail:'Bangkok · 14–15 Oct · 1 adult',provider:'Nuitée',providerEnv:'Sandbox',agent:'ChatGPT',channel:'External agent',rail:'Cardano',network:'Preprod',amount:18400,newAmount:19700,ceiling:22000,request:'Book one night in Bangkok, with a total under US$220.',status:'succeeded',time:'9:40 AM',reference:'DEMO-NUITEE-023'},
 {id:'0424',kind:'retail',name:'Everyday carry bag',offer:'Carry bag · sample product',detail:'1 item · delivery included',provider:'Shopify',providerEnv:'Test store',agent:'ChatGPT',channel:'External agent',rail:'Cardano',network:'Preprod',amount:6200,newAmount:6900,ceiling:8000,request:'Buy this carry bag from the test store for no more than US$80 including delivery.',status:'requires_reauthorization',time:'9:25 AM',reference:'DEMO-SHOPIFY-1041'},
 {id:'0423',kind:'task',name:'Commerce task',offer:'Purchase request',detail:'Awaiting separately funded purchase principal',provider:'Gateway',providerEnv:'Design scenario',agent:'Sokosumi',channel:'Commerce task',rail:'Masumi',network:'Preprod',amount:14400,newAmount:14400,ceiling:16000,request:'Complete this purchase task within a US$160 limit.',status:'awaiting_funding',time:'9:10 AM',reference:null,feeOnly:true}
];
// Live preview state is deliberately ephemeral: reloading resets it.
let selected=structuredClone(allSamples[0]);
let view='detail',reviewScreen='progress',filter='all',query='',inspectorTab='summary',drawerOpen=false;
let playing=false,playTimers=[],toastTimer=null,lastFocused=null,fundingChoice=null;
const el=id=>document.getElementById(id);
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(n=>{n.innerHTML=icon(n.dataset.icon);n.removeAttribute('data-icon')})}
paintIcons();
function statusLabel(status){return ({awaiting_funding:'Awaiting payment',funded_queued:'Payment confirmed',executing:'In progress',succeeded:'Completed',requires_reauthorization:'Needs review',unresolved:'Checking outcome',failed:'Not completed',expired:'Quote expired'})[status]||'Not available'}
function badge(status,label){const cls=({succeeded:'complete',executing:'progress',funded_queued:'progress',requires_reauthorization:'review',unresolved:'review',awaiting_funding:'pending'})[status]||'pending';return `<span class="badge ${cls}"><span class="status-dot"></span>${esc(label||statusLabel(status))}</span>`}
function paid(){return ['funded_queued','executing','succeeded','requires_reauthorization','unresolved'].includes(selected.status)}
function complete(){return selected.status==='succeeded'}
function outcome(){if(!complete())return null;return selected.kind==='flight'?'Ticket issued':selected.kind==='retail'?'Order paid':'Booking confirmed'}
function proofCount(){return (paid()?1:0)+(complete()?1:0)}
function fullId(){return 'DEMO-CAP-'+selected.id}
function railIcon(){return selected.rail==='Masumi'?icon('layers'):icon('wallet')}
function getSnapshot(){
 const isPaid=paid(),done=complete(),review=selected.status==='requires_reauthorization';
 return {disclosure:'ILLUSTRATIVE DESIGN FIXTURE — NOT EXTERNAL EVIDENCE',purchaseId:fullId(),state:selected.status,paymentState:isPaid?'confirmed':'not_received',commerceStatus:done?(selected.kind==='retail'?'paid':selected.kind==='flight'?'ticketed':'confirmed'):selected.status==='unresolved'?'unknown':'not_started',merchantPaymentStatus:done?(selected.kind==='flight'?'test_balance_paid':'simulated_paid'):'none',payablePrincipal:{currency:'USD',amountMinor:String(selected.amount),scale:2},agent:selected.agent,rail:selected.rail,network:selected.network,provider:selected.provider,providerEnvironment:selected.providerEnv,evidenceMode:'local_fixture',providerReference:done?selected.reference:null,fundingReference:isPaid?'DEMO-TX-'+selected.id+'-001':null,reservation:isPaid?(done?'consumed':review?'held_unresolved':'active'):null,ledgerMode:'simulated',quoteId:'DEMO-QUOTE-'+selected.id+'-V1',proposedQuoteId:review?'DEMO-QUOTE-'+selected.id+'-V2':null,receipt:done?{receiptId:'DEMO-RECEIPT-'+selected.id,limitations:['Illustrative fixture only. No chain transaction or provider operation occurred.','No production bank settlement, crypto-to-fiat conversion or physical fulfillment is demonstrated.']}:null};
}
function disclosure(){return `<div class="caption-bar"><span>${icon('flask')}Design fixture · ${esc(selected.rail)} ${esc(selected.network)} · ${esc(selected.provider)} ${esc(selected.providerEnv)}</span><span>Simulated purchasing capacity. No payments or bookings are made.</span></div>`}
function titleBlock(){return `<div class="purchase-heading"><div><div class="heading-line"><h1>Purchase #${esc(selected.id)}</h1><button class="icon-button" data-copy="${esc(fullId())}" aria-label="Copy purchase ID" title="Copy purchase ID">${icon('copy')}</button></div><div class="subhead"><span>${esc(selected.agent)}</span><span class="dot-separator">·</span><span>Today, ${esc(selected.time)}</span><span class="dot-separator">·</span>${badge(selected.status)}</div></div><div><div class="price-label">Purchase total</div><div class="price num">${dollars(selected.amount)}<span class="currency">USD</span></div></div></div><div class="request"><div class="request-icon">${icon('chat')}</div><div><p class="request-text">“${esc(selected.request)}”</p><div class="request-approval">${icon('approval')}Original quote ${fmt(selected.amount)} approved · Ceiling ${fmt(selected.ceiling)}</div></div></div>`}
function routeBlock(){
 const stopped=['requires_reauthorization','unresolved'].includes(selected.status), done=complete();
 const action=stopped?'Execution paused':done?'Execution complete':selected.status==='awaiting_funding'?'Awaiting purchase funds':selected.status==='funded_queued'?'Ready for execution':'Executing purchase';
 const result=done?outcome():selected.status==='requires_reauthorization'?'No purchase made':selected.status==='unresolved'?'Outcome not yet known':'Confirmation pending';
 return `<section class="route-panel" aria-label="Purchase route from agent to commerce"><div class="route-top"><h2 class="micro-label">Purchase route</h2><span class="route-mode">${icon('layers')}One linked purchase</span></div><div class="route"><div class="endpoint"><div class="endpoint-label">Agent & funding</div><div class="endpoint-heading"><div class="endpoint-icon">${icon('agent')}</div><div><h3>${esc(selected.agent)}</h3><small>${esc(selected.channel)}</small></div></div><div class="endpoint-funding">${railIcon()}<span>${esc(selected.rail)}</span><span class="endpoint-network">${esc(selected.network)}</span></div></div><div class="conduit ${paid()?'done':''}" aria-hidden="true"><span class="packet"></span></div><div class="gateway-node ${stopped?'stopped':''}"><div class="gateway-label">Gateway</div><div class="gateway-symbol"><img src="${LOGOS.mark}" alt="Capsule gateway"></div><img class="gateway-word" src="${LOGOS.mono}" alt="Capsule"><span class="gateway-action">${esc(action)}</span></div><div class="conduit ${done?'done':'dashed'}" aria-hidden="true">${!stopped?'<span class="packet"></span>':''}</div><div class="endpoint"><div class="endpoint-label">Real-world commerce</div><div class="endpoint-heading"><div class="endpoint-icon">${icon(selected.kind==='task'?'purchases':selected.kind)}</div><div><h3>${esc(selected.provider)}</h3><small>${esc(selected.providerEnv)}</small></div></div><div class="endpoint-result ${done?'verified':''}">${done?icon('check'):icon(stopped?'pause':'receipt')}<span>${esc(result)}</span></div></div></div></section>`;
}
function eventTime(seconds){const [h,m]=selected.time.split(' ')[0].split(':').map(Number);const hr=selected.time.includes('PM')?h%12+12:h%12;return `${String(hr).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`}
function stepsData(){
 const s=selected.status, done=complete(), funded=paid();
 return [
  {name:'Request approved',detail:'Original quote bound to a spending limit.',phase:'done',time:eventTime(8)},
  {name:'Payment confirmed',detail:funded?`${selected.rail} ${selected.network} · ${fmt(selected.amount)} quote value.`:selected.feeOnly?'Task fees do not fund this purchase.':'Waiting for purchase funding.',phase:funded?'done':s==='awaiting_funding'?'current':'pending',time:funded?eventTime(12):'Pending'},
  {name:'Purchase execution',detail:done?'Provider operation completed.':s==='funded_queued'?'Funding checked. Waiting for execution.':s==='awaiting_funding'?'Begins after verified purchase funding.':'Purchasing capacity reserved; provider request underway.',phase:done?'done':s==='executing'?'current':'pending',time:done?eventTime(23):s==='executing'?'In progress':'Pending'},
  {name:'Provider confirmation',detail:done?`${outcome()}. Receipt available.`:'Independent provider result not received yet.',phase:done?'done':'pending',time:done?eventTime(24):'Pending'}
 ];
}
function activityBlock(){
 if(selected.status==='requires_reauthorization')return reviewBlock();
 const steps=stepsData();const finished=steps.filter(s=>s.phase==='done').length;
 return `<section class="activity-section"><div class="section-heading"><h2>${complete()?'Purchase complete':'Purchase progress'}</h2><span class="micro-count">${finished} of 4 complete</span></div><ol class="steps">${steps.map((s,i)=>`<li class="step ${s.phase}"><span class="step-circle">${s.phase==='done'?icon('check'):s.phase==='current'?'':i+1}</span><div><strong>${s.name}</strong><p>${esc(s.detail)}</p></div><time>${esc(s.time)}</time></li>`).join('')}</ol><div class="progress-foot">${complete()?`<button class="quiet-link" data-action="receipt">${icon('receipt')}Open receipt ${icon('external')}</button>`:`<button class="quiet-link" data-action="audit">${icon('history')}Open audit trail${icon('arrow')}</button>`}<button class="btn evidence-primary" data-action="evidence">${icon('receipt')}Evidence <span class="muted">${proofCount()}/2</span>${icon('arrow')}</button></div></section>`;
}
function propertiesBlock(){
 return `<aside class="properties" aria-label="Purchase summary"><h2>Purchase summary</h2><div class="summary-inner"><div><div class="offer-mini"><div class="offer-icon">${icon(selected.kind==='task'?'purchases':selected.kind)}</div><div><strong>${esc(selected.offer)}</strong><small>${esc(selected.detail)}</small></div></div><dl class="costs"><div><dt>Merchant total</dt><dd>${dollars(selected.amount)}</dd></div><div><dt>Capsule fee</dt><dd>$0.00</dd></div><div class="total-row"><dt>Total</dt><dd>${dollars(selected.amount)} USD</dd></div></dl><button class="quiet-link" data-action="quote" style="margin-top:10px">View quote & terms ${icon('external')}</button></div><div><section class="property-section"><div class="small-heading"><span>Funding method</span>${selected.status==='awaiting_funding'&&!selected.feeOnly?'<button class="quiet-link" data-action="funding">Change</button>':''}</div><div class="inline-funding">${railIcon()}${esc(selected.rail)} <span class="badge outline">${esc(selected.network)}</span></div><p class="fineprint">${paid()?dollars(selected.amount).slice(1)+' test units · illustrative asset':selected.feeOnly?'Purchase principal still required.':'Choose a funding method before payment.'}</p><div class="lock-line">${icon(paid()?'lock':'wallet')}${paid()?'Funding confirmed; method locked.':'No purchase payment received.'}</div></section></div></div></aside>`;
}
function reviewBlock(){return `<section class="activity-section"><div class="section-heading"><h2>Review the changed quote</h2><span class="badge review">Approval needed</span></div><table class="review-table"><thead><tr><th>Price breakdown</th><th>Approved</th><th>New quote</th></tr></thead><tbody><tr><td>Merchant total</td><td>${dollars(selected.amount)}</td><td class="highlight">${dollars(selected.newAmount)}</td></tr><tr><td>Capsule fee</td><td>$0.00</td><td>$0.00</td></tr><tr><td>Total · USD</td><td>${dollars(selected.amount)}</td><td class="highlight">${dollars(selected.newAmount)}</td></tr></tbody></table><p class="review-summary">The ${fmt(selected.newAmount-selected.amount)} increase is below your ceiling, but changes the exact terms you approved. Capsule has paused the purchase.</p><p class="review-step-note">${icon('lock')}Existing payment remains linked to the original quote.</p><div class="action-row"><button class="btn" data-action="evidence">View existing payment</button><button class="btn primary" data-action="review-quote">Review new quote ${icon('arrow')}</button></div></section>`}
function detailPage(){return titleBlock()+(selected.status==='requires_reauthorization'?`<div class="status-message">${icon('alert')}<div><h2>The quote changed. The purchase did not go through.</h2><p>No new payment or merchant execution will be initiated by this preview.</p></div></div>`:'')+routeBlock()+`<div class="detail-grid">${activityBlock()}${propertiesBlock()}</div>`+disclosure()}
function historyData(){return allSamples.filter(p=>filter==='all'||filter==='progress'&&['executing','funded_queued','awaiting_funding'].includes(p.status)||filter==='review'&&p.status==='requires_reauthorization'||filter==='complete'&&p.status==='succeeded').filter(p=>[p.name,p.agent,p.provider,p.id,p.rail].join(' ').toLowerCase().includes(query.toLowerCase()))}
function historyPage(){const rows=historyData();const totals={all:allSamples.length,progress:allSamples.filter(p=>['executing','funded_queued','awaiting_funding'].includes(p.status)).length,review:allSamples.filter(p=>p.status==='requires_reauthorization').length,complete:allSamples.filter(p=>p.status==='succeeded').length};return `<div class="history-heading"><div><h1>Purchases</h1><p class="history-subhead">Every agent. Every purchase. One place to follow through.</p></div><button class="btn" data-action="export-history">${icon('download')}Export sample</button></div><div class="history-controls"><div class="tabs" role="tablist" aria-label="Filter purchases by state">${[['all','All purchases',totals.all],['progress','In progress',totals.progress],['review','Needs review',totals.review],['complete','Completed',totals.complete]].map(([f,l,n])=>`<button class="tab ${filter===f?'active':''}" role="tab" aria-selected="${filter===f}" tabindex="${filter===f?'0':'-1'}" data-filter="${f}">${l}<span class="tab-count">${n}</span></button>`).join('')}</div></div><div class="table-tools"><label class="search">${icon('search')}<input id="purchase-search" type="search" aria-label="Search purchases" placeholder="Search purchase, agent, provider…" value="${esc(query)}"></label><span class="table-note">6 Oct 2026 · Example purchase history</span></div><div class="history-wrap"><table class="history-table"><thead><tr><th>Purchase</th><th>Agent</th><th>Funding</th><th>Amount · USD</th><th>Status</th><th><span class="sr-only">Open purchase</span></th></tr></thead><tbody>${rows.map(p=>`<tr data-id="${p.id}" tabindex="0" aria-label="Open purchase ${p.id}: ${esc(p.name)}"><td><div class="row-name"><span class="row-category">${icon(p.kind==='task'?'purchases':p.kind)}</span><div><strong>${esc(p.name)}</strong><small>#${p.id} · ${esc(p.provider)} · ${esc(p.time)}</small></div></div></td><td>${esc(p.agent)}</td><td class="rail-cell">${esc(p.rail)}<small>${esc(p.network)}${p.feeOnly?' · purchase unfunded':''}</small></td><td class="num">${dollars(p.amount)}</td><td>${badge(p.status)}</td><td class="table-arrow">${icon('chevron')}</td></tr>`).join('')}</tbody></table>${rows.length?'':`<div class="empty"><h2>No matching purchases</h2><p>Try an agent name, provider or purchase number.</p><button class="quiet-link" data-action="clear-search" style="margin-top:15px">Clear search ${icon('arrow')}</button></div>`}</div><div class="table-footer"><span>Showing ${rows.length} of 6 sample purchases</span><span>All amounts are illustrative.</span></div>`}
function render({preserveSearch=false}={}){
 if(view==='detail'){const index=allSamples.findIndex(p=>p.id===selected.id);if(index>=0)allSamples[index]=structuredClone(selected)}
 el('review-count').textContent=allSamples.filter(p=>p.status==='requires_reauthorization').length;
 const position=preserveSearch&&document.activeElement?.id==='purchase-search'?document.activeElement.selectionStart:null;
 el('main').innerHTML=view==='history'?historyPage():detailPage();
 el('crumb').textContent=view==='history'?'All agents':'DEMO-'+selected.id;
 el('nav-live').classList.toggle('selected',view==='detail');el('nav-history').classList.toggle('selected',view==='history'&&filter!=='review');el('nav-review').classList.toggle('selected',view==='history'&&filter==='review');
 document.querySelectorAll('[data-screen]').forEach(b=>{b.classList.toggle('active',b.dataset.screen===reviewScreen);b.setAttribute('aria-pressed',b.dataset.screen===reviewScreen)});
 document.body.classList.toggle('playing',playing);
 el('play-button').innerHTML=icon(playing?'stop':'play')+`<span>${playing?'Stop sample':'Run sample'}</span>`;
 if(preserveSearch&&position!==null){const n=el('purchase-search');n.focus();try{n.setSelectionRange(position,position)}catch{}}
 if(drawerOpen)renderInspector();
}
function stopPlayback(){playTimers.forEach(clearTimeout);playTimers=[];playing=false;document.body.classList.remove('playing');const b=el('play-button');if(b)b.innerHTML=icon('play')+'<span>Run sample</span>'}
function setReviewScreen(screen){
 stopPlayback();closeInspector(false);if(el('modal').open)el('modal').close();reviewScreen=screen;
 if(screen==='history'){view='history';filter='all';query='';document.body.classList.remove('focus')}
 else {view='detail';if(!['0428','0427'].includes(selected.id)){selected=structuredClone(allSamples[el('scenario').value==='retail'?1:0])}
 selected.status=screen==='review'?'requires_reauthorization':screen==='complete'||screen==='evidence'?'succeeded':'executing'}
 render();window.scrollTo(0,0);if(screen==='evidence')openInspector('summary');
}
function openPurchase(id){const p=allSamples.find(p=>p.id===id);if(!p)return;stopPlayback();closeInspector(false);selected=structuredClone(p);view='detail';reviewScreen=selected.status==='succeeded'?'complete':selected.status==='requires_reauthorization'?'review':'progress';render();window.scrollTo(0,0)}
function events(){const data=stepsData();if(selected.status==='requires_reauthorization')return [
 {name:'Original quote approved',detail:'DEMO-QUOTE-'+selected.id+'-V1',time:eventTime(8)},
 {name:'Original purchase funding confirmed',detail:'DEMO-TX-'+selected.id+'-001',time:eventTime(12)},
 {name:'Provider recheck returned changed terms',detail:'Proposed total '+fmt(selected.newAmount),time:eventTime(17)},
 {name:'Execution paused for fresh authority',detail:'No new provider purchase initiated.',time:eventTime(18)}
 ];return data.filter(e=>e.phase==='done'||e.phase==='current').map(e=>({name:e.name,detail:e.detail,time:e.time==='Pending'?'Not received':e.time}))}
function renderInspector(){
 const s=getSnapshot();el('inspector-meta').innerHTML=`<span class="mono">${esc(fullId())}</span><span>·</span>${badge(selected.status)}`;
 document.querySelectorAll('[data-evidence]').forEach(b=>{b.classList.toggle('active',b.dataset.evidence===inspectorTab);b.setAttribute('aria-selected',b.dataset.evidence===inspectorTab);b.tabIndex=b.dataset.evidence===inspectorTab?0:-1});el('evidence-body').setAttribute('aria-labelledby',`evidence-${inspectorTab}-tab`);
 const disclaimer='<div class="evidence-disclaimer">Sample records only. These references do not point to real chain transactions or provider bookings.</div>';
 if(inspectorTab==='audit'){
 el('evidence-body').innerHTML=disclaimer+events().map((e,i)=>`<div class="audit-item"><span class="audit-index">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><p>${esc(e.detail)}</p><p class="mono">${esc(e.time)} · local_fixture</p></div></div>`).join('')+`<details style="margin-top:20px"><summary style="font-size:11px;color:var(--muted);cursor:pointer">Show redacted state record</summary><pre class="raw-audit">${esc(JSON.stringify(s,null,2))}</pre></details>`;return;
 }
 const field=(k,v)=>`<dt>${esc(k)}</dt><dd>${v}</dd>`;
 el('evidence-body').innerHTML=disclaimer+`<section class="proof-block"><div class="proof-title"><h3>${icon('wallet')}Payment</h3>${badge(paid()?'succeeded':'awaiting_funding',paid()?'Confirmed':'Not received')}</div><dl class="evidence-dl">${field('Funding rail',esc(selected.rail+' · '+selected.network))}${field('Quote value',fmt(selected.amount))}${field('Purpose','Purchase principal')}${field('Asset',paid()?dollars(selected.amount).slice(1)+' CAP-DEMO units':'No purchase funding')}${field('Valuation','Illustrative 1 unit = US$1; no market value')}</dl>${paid()?`<div class="reference-box"><div><p>Sample transfer reference</p><span class="mono">${esc(s.fundingReference)}</span></div><button class="icon-button" data-copy="${esc(s.fundingReference)}" aria-label="Copy sample transfer reference">${icon('copy')}</button></div>`:selected.feeOnly?'<p class="info-box">A Masumi task fee or escrow is separate from purchase principal. It is not a paid commerce result.</p>':'<p class="no-evidence" style="margin-top:13px">No payment record is available yet.</p>'}</section><section class="proof-block"><div class="proof-title"><h3>${icon('receipt')}Provider result</h3>${badge(complete()?'succeeded':'awaiting_funding',complete()?'Confirmed':'Pending')}</div><dl class="evidence-dl">${field('Provider',esc(selected.provider))}${field('Environment',esc(selected.providerEnv))}${field('Commerce state',complete()?esc(outcome()):selected.status==='requires_reauthorization'?'Not purchased':'Not confirmed')}${field('Merchant payment',complete()?selected.kind==='flight'?'Test balance paid':'Simulated paid':'Not confirmed')}</dl>${complete()?`<div class="reference-box"><div><p>Sample provider reference</p><span class="mono">${esc(selected.reference)}</span></div><button class="icon-button" data-copy="${esc(selected.reference)}" aria-label="Copy sample provider reference">${icon('copy')}</button></div>`:'<p class="no-evidence" style="margin-top:13px">A payment confirmation alone is not a provider confirmation. No completed receipt is shown.</p>'}</section><section class="proof-block"><div class="proof-title"><h3>${icon('layers')}Purchasing capacity</h3><span class="badge outline">Simulated</span></div><dl class="evidence-dl">${field('Reservation',complete()?'Consumed':paid()?'Held for this purchase':'Not reserved')}${field('Amount',paid()?fmt(selected.amount):'—')}${field('Bank settlement','Not demonstrated')}${field('Crypto conversion','Not demonstrated')}</dl></section>`;
}
function openInspector(tab='summary'){
 stopPlayback();lastFocused=document.activeElement;inspectorTab=tab;drawerOpen=true;renderInspector();el('inspector').classList.add('open');el('inspector').inert=false;el('inspector').setAttribute('aria-hidden','false');el('scrim').classList.add('open');document.querySelector('.shell').inert=true;document.querySelector('.review-dock').inert=true;el('inspector').querySelector('[data-action="close-inspector"]').focus();el('play-button').innerHTML=icon('play')+'<span>Run sample</span>';document.body.classList.remove('playing');
}
function closeInspector(restore=true){drawerOpen=false;el('inspector').classList.remove('open');el('inspector').setAttribute('aria-hidden','true');el('inspector').inert=true;el('scrim').classList.remove('open');document.querySelector('.shell').inert=false;document.querySelector('.review-dock').inert=false;if(restore&&lastFocused?.isConnected)lastFocused.focus()}
function showModal(title,body){stopPlayback();if(drawerOpen)closeInspector();el('modal-title').textContent=title;el('modal-body').innerHTML=body;if(!el('modal').open)el('modal').showModal()}
function closeModal(){el('modal').close()}
function showQuote(revised=false){
 if(revised){showModal('Review the updated quote',`<p class="dialog-intro">The purchase remains paused. Approval must cover the new quote, not just the original spending ceiling.</p><table class="review-table"><thead><tr><th>Purchase</th><th>Original · V1</th><th>Proposed · V2</th></tr></thead><tbody><tr><td>Merchant amount</td><td>${fmt(selected.amount)}</td><td class="highlight">${fmt(selected.newAmount)}</td></tr><tr><td>Service fee</td><td>US$0.00</td><td>US$0.00</td></tr><tr><td>Total</td><td>${fmt(selected.amount)}</td><td class="highlight">${fmt(selected.newAmount)}</td></tr></tbody></table><div class="quote-scope"><div><span>Provider</span><span>${esc(selected.provider)} · ${esc(selected.providerEnv)}</span></div><div><span>Purchase</span><span>${esc(selected.detail)}</span></div><div><span>Spending ceiling</span><span>${fmt(selected.ceiling)}</span></div><div><span>Fulfillment</span><span>Unchanged in this sample</span></div><div><span>Proposed quote</span><span class="mono">DEMO-QUOTE-${selected.id}-V2</span></div></div><p class="info-box">Copy the exact request to the external agent for approval. This preview does not authorize the new quote, move the earlier payment, or assume a funding top-up.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Keep paused</button><button class="btn primary" data-action="copy-approval">${icon('copy')}Copy approval request</button></div>`);return}
 showModal('Original quote & terms',`<p class="dialog-intro">A design fixture of the exact terms attached to this purchase.</p><div class="quote-scope"><div><span>Quote</span><span class="mono">DEMO-QUOTE-${selected.id}-V1</span></div><div><span>Merchant</span><span>${esc(selected.provider)}</span></div><div><span>Selection</span><span>${esc(selected.offer)}</span></div><div><span>Fulfillment</span><span>${esc(selected.detail)}</span></div><div><span>Merchant amount</span><span>${fmt(selected.amount)}</span></div><div><span>Service fee</span><span>US$0.00</span></div><div><span>Approved total</span><strong>${fmt(selected.amount)}</strong></div><div><span>Maximum ceiling</span><span>${fmt(selected.ceiling)}</span></div></div><p class="info-box">Taxes and ${selected.kind==='retail'?'delivery':'listed provider charges'} are included in this sample total. Real cancellation conditions, quote expiry and fulfillment terms must come from the executable quote; none are invented here.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Close quote</button></div>`);
}
function showReceipt(){if(!complete()){toast('A receipt is available only after provider confirmation.');return}showModal('Purchase receipt',`<img class="receipt-brand" src="${LOGOS.accent}" alt="Capsule"><span class="badge complete">${icon('check')}Completed · design fixture</span><div class="receipt-total num">${dollars(selected.amount)} <small>USD</small></div><p style="font-size:13px">${esc(selected.offer)}</p><div class="receipt-meta"><div><span>Requested through</span><span>${esc(selected.agent)}</span></div><div><span>Funding</span><span>${esc(selected.rail+' · '+selected.network)}</span></div><div><span>Provider</span><span>${esc(selected.provider+' · '+selected.providerEnv)}</span></div><div><span>Result</span><span>${esc(outcome())}</span></div><div><span>Reference</span><span class="mono">${esc(selected.reference)}</span></div></div><p class="receipt-note">Illustrative receipt. No transaction, real reservation, production bank settlement or physical fulfillment is claimed.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="export-receipt">${icon('download')}Save sample receipt</button></div>`)}
function showFunding(){if(paid()){toast('Funding is already confirmed. Its method cannot be changed.');return}if(selected.feeOnly){toast('Task fees and purchase principal remain separate.');return}fundingChoice=selected.rail;fundingModal()}
function fundingModal(){showModal('Choose purchase funding',`<p class="dialog-intro">The funding method is explicit before payment. These choices preview the interface, not integration readiness.</p>${[['Cardano','Preprod','wallet'],['Solana','Devnet','layers']].map(([r,n,i])=>`<button class="funding-option ${fundingChoice===r?'checked':''}" data-rail="${r}"><span class="funding-symbol">${icon(i)}</span><span><strong>${r}</strong><small>${n} · test-asset design fixture</small></span><span class="radio" aria-hidden="true"></span></button>`).join('')}<button class="funding-option" disabled aria-disabled="true"><span class="funding-symbol">${icon('card')}</span><span><strong>Card · Stripe</strong><small>Not implemented in this demo</small></span><span class="badge outline">Unavailable</span></button><p class="info-box">No keys, wallet connection or signing occurs here. Confirming a method only changes the local sample selection.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="choose-funding">Use ${esc(fundingChoice)} in preview ${icon('arrow')}</button></div>`)}
function referencesModal(){showModal('Research behind this revision',`<p class="dialog-intro">Actual Mobbin screens inspected for this pass. The approved Capsule colours and logos are retained; the page composition is new.</p>${REFERENCES.map(r=>`<section class="reference-study"><h3>${esc(r.name)} · ${esc(r.focus)}</h3><p><strong>Observed:</strong> ${esc(r.observed)}</p><p><strong>Applied:</strong> ${esc(r.applied)}</p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">View the exact Mobbin reference ${icon('external')}</a></section>`).join('')}<p class="info-box">The agent → Capsule → commerce route is a Capsule-specific proposal, not a component attributed to these products. Reference screenshots are not bundled; the canonical links open the originals.</p>`)}
function aboutModal(){showModal('About this prototype',`<p class="dialog-intro">A visual review of Capsule’s purchase workspace, not an implemented payment product.</p><div class="quote-scope"><div><span>Data</span><span>Local, illustrative fixtures</span></div><div><span>Real payments</span><span>None</span></div><div><span>Provider calls</span><span>None</span></div><div><span>Backend changes</span><span>None</span></div><div><span>Logo artwork</span><span>Approved mono, accent and graphic crops</span></div></div><p class="info-box">The five review buttons show progress, completion, evidence, changed terms and history. “Run sample” plays a short local fixture sequence. Presentation layout enlarges the same design instead of switching to an unrelated theme.</p><div class="modal-footer"><button class="btn" data-action="close-modal">Back to preview</button><button class="btn primary" data-action="references">View research ${icon('arrow')}</button></div>`)}
function toast(text){el('toast').textContent=text;el('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.remove('show'),3500)}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const t=document.createElement('textarea');t.value=text;t.style.cssText='position:fixed;top:-9999px';(el('modal').open?el('modal'):document.body).append(t);t.select();if(!document.execCommand('copy'))throw Error('Clipboard unavailable');t.remove()}toast('Copied to clipboard.')}catch{showModal('Copy this text',`<p class="dialog-intro">Clipboard access is unavailable in this browser context. Select and copy the text below.</p><textarea aria-label="Text to copy" readonly style="width:100%;height:120px;padding:12px;border:1px solid var(--line);border-radius:7px">${esc(text)}</textarea>`)} }
function downloadJSON(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample JSON exported. No live records.');}
function runSample(){if(playing){stopPlayback();render();return}closeInspector(false);if(el('modal').open)closeModal();selected=structuredClone(allSamples[el('scenario').value==='retail'?1:0]);selected.status='awaiting_funding';view='detail';reviewScreen='progress';playing=true;render();toast('Playing a local design fixture — no payments or orders.');[[2200,'funded_queued'],[3800,'executing'],[7800,'succeeded']].forEach(([delay,status])=>playTimers.push(setTimeout(()=>{selected.status=status;if(status==='succeeded'){reviewScreen='complete';playing=false;playTimers=[]}render()},delay)))}
const actions={
 live:()=>{setReviewScreen('progress')},history:()=>{setReviewScreen('history')},'review-queue':()=>{stopPlayback();closeInspector(false);view='history';reviewScreen='history';filter='review';query='';document.body.classList.remove('focus');render()},
 evidence:()=>openInspector('summary'),audit:()=>openInspector('audit'),'close-inspector':()=>closeInspector(),
 receipt:showReceipt,quote:()=>showQuote(false),'review-quote':()=>showQuote(true),
 'copy-approval':()=>copyText(`Review and request approval for DEMO-QUOTE-${selected.id}-V2: ${selected.offer}; ${selected.detail}; merchant ${selected.provider}; total ${fmt(selected.newAmount)} inclusive of US$0.00 service fee; ceiling ${fmt(selected.ceiling)}. Earlier funding remains attached to V1. Revalidate expiry and funding requirements before execution. DESIGN FIXTURE ONLY.`),
 funding:showFunding,'choose-funding':()=>{if(paid())return;selected.rail=fundingChoice;selected.network=fundingChoice==='Cardano'?'Preprod':'Devnet';closeModal();render();toast('Preview method changed. No funds sent.');},
 'export-evidence':()=>downloadJSON({...getSnapshot(),events:events()},`capsule-${selected.id}-sample-evidence.json`),
 'export-receipt':()=>{if(complete())downloadJSON(getSnapshot(),`capsule-${selected.id}-sample-receipt.json`)},
 'export-history':()=>downloadJSON({disclosure:'DESIGN FIXTURE — NO LIVE TRANSACTIONS',purchases:allSamples},'capsule-sample-purchases.json'),
 'clear-search':()=>{query='';render();el('purchase-search')?.focus()},'close-modal':closeModal,
 focus:()=>{document.body.classList.toggle('focus');toast(document.body.classList.contains('focus')?'Presentation layout. Same purchase, fewer controls.':'Workspace layout restored.')},
 references:referencesModal,about:aboutModal,play:runSample
};
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a[data-action],tr[data-id],[data-action="close-inspector"]');if(!b||b.disabled)return;
 if(b.dataset.screen){setReviewScreen(b.dataset.screen);return}
 if(b.dataset.filter){filter=b.dataset.filter;render();document.querySelector(`[data-filter="${filter}"]`)?.focus();return}
 if(b.dataset.id){openPurchase(b.dataset.id);return}
 if(b.dataset.copy){copyText(b.dataset.copy);return}
 if(b.dataset.evidence){inspectorTab=b.dataset.evidence;renderInspector();return}
 if(b.dataset.rail){fundingChoice=b.dataset.rail;fundingModal();return}
 if(b.dataset.action&&actions[b.dataset.action]){e.preventDefault();actions[b.dataset.action]()}
});
document.addEventListener('input',e=>{if(e.target.id==='purchase-search'){query=e.target.value;render({preserveSearch:true})}});
el('scenario').addEventListener('change',()=>{selected=structuredClone(allSamples[el('scenario').value==='retail'?1:0]);setReviewScreen('progress')});
el('modal').addEventListener('click',e=>{if(e.target===el('modal')){const r=el('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&drawerOpen){e.preventDefault();closeInspector();return}
 if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-id]')){e.preventDefault();openPurchase(e.target.dataset.id);return}
 // Arrow navigation preserves familiar tab interaction for both filter and inspector tabs.
 if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)&&e.target.getAttribute('role')==='tab'){
  const tabs=[...e.target.parentElement.querySelectorAll('[role="tab"]')],i=tabs.indexOf(e.target);let n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[n].click();document.getElementById(tabs[n].id)?.focus();if(tabs[n].dataset.filter)document.querySelector(`[data-filter="${tabs[n].dataset.filter}"]`)?.focus();return;
 }
 if(e.key==='Tab'&&drawerOpen){const nodes=[...el('inspector').querySelectorAll('button:not([disabled]):not([tabindex="-1"]),a[href],summary')].filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
});
// Query parameters only select a local review state; they never trigger a real operation.
const params=new URLSearchParams(location.search);
if(params.get('scenario')==='retail'){el('scenario').value='retail';selected=structuredClone(allSamples[1])}
if(params.get('focus')==='1')document.body.classList.add('focus');
const initial=params.get('screen');if(['progress','complete','evidence','review','history'].includes(initial))setReviewScreen(initial);else render();
